--time=WORD            select which timestamp used to display or sort;
                         access time (-u): atime, access, use;
                         metadata change time (-c): ctime, status;
                         modified time (default): mtime, modification;
                         birth time: birth, creation;
                       with -l, WORD determines which time to show;
                       with --sort=time, sort by WORD (newest first)

--time=ORD             välj vilka tidsstämplar som används för att visa
                       eller sortera:
                         åtkomsttid (-u): atime, access, use;
                         metadataändringstid (-c): ctime, status;
                         modifieringstid (standard); mtime, modification;
                         födelsetid: birth, creation;
                       med -l avgör ORD vilken tid att visa;
                       med --sort=time, sortera enligt ORD (nyast först)

--time=WORD        specify which time to change:
                     access time (-a): 'access', 'atime', 'use';
                     modification time (-m): 'modify', 'mtime'

--time=ORD         ange vilken tid att ändra:
                     åtkomsttid (-a): ”access”, ”atime”, ”use”;
                     ändringstid (-m): ”modify”, ”mtime”

    --update[=UPDATE]        control which existing files are updated;
                               UPDATE={all,none,none-fail,older(default)}
-u                           equivalent to --update[=older].  See below

    --update[=UPPDATERA]         styr vilka befintliga filer som uppdateras;
                               UPPDATERA={all,none,none-fail,older(standard)}
-u                           ekvivalent med --update[=older]. Se nedan

--z85             ascii85-like encoding (ZeroMQ spec:32/Z85);
                  when encoding, input length must be a multiple of 4;
                  when decoding, input length must be a multiple of 5

--z85             ascii85-liknande kodning (ZeroMQ spec:32/Z85);
                  vid kodning måste indatalängden vara en multipel av 4;
                  vid avkodning måste indatalängden vara en multipel av 5

-D                    print all duplicate lines
    --all-repeated[=METHOD]  like -D, but allow separating groups
                               with an empty line;
                               METHOD={none(default),prepend,separate}

-D                    skriv ut alla upprepade rader
    --all-repeated[=METOD]  som -D, men tillåt att grupper separeras
                              med en tom rad;
                              METOD={none(standard),prepend,separate}

-D                  skapa alla föräldrakataloger till DEST utom den sista;
                      eller alla komponenter av --target-directory,
                      kopiera sedan KÄLLA till DEST

-c                         with -lt: sort by, and show, ctime (time of last
                           change of file status information);
                           with -l: show ctime and sort by name;
                           otherwise: sort by ctime, newest first

-c                         med -lt: sortera efter och visa ctime, (tid för
                             senaste ändring av filstatusinformation);
                             med -l: visa ctime och sortera efter namn;
                             annars: sortera efter ctime, nyast först

-c  --format=FORMAT   use the specified FORMAT instead of the default;
                        output a newline after each use of FORMAT
    --printf=FORMAT   like --format, but interpret backslash escapes,
                        and do not output a mandatory trailing newline;
                        if you want a newline, include \n in FORMAT
-t, --terse           print the information in terse form

-c, --bytes=[-]NUM       print the first NUM bytes of each file;
                           with the leading '-', print all but the last
                           NUM bytes of each file
-n, --lines=[-]NUM       print the first NUM lines instead of the first %d;
                           with the leading '-', print all but the last
                           NUM lines of each file

-c, --bytes=[-]ANT       skriv de första ANT byte av varje fil;
                           med det inledande ”-”, skriv allt utom de sista
                           ANT byte av varje fil
-n, --lines=[-]ANT       skriv de första ANT raderna istället för de första %d;
                           med det inledande ”-”, skriv alla utom de sista
                           ANT raderna av varje fil

-n, --numeric-sort          jämför enligt strängens numeriska värde;
                              se den fullständiga dokumentationen för
                              vilka strängar som stödjs

-s, --signal=SIGNAL
               specify the signal to be sent on timeout;
                 SIGNAL may be a name like 'HUP' or a number;
                 see 'kill -l' for a list of signals

-s, --signal=SIGNAL
               ange signalen som skall skickas när tiden går ut;
                 SIGNAL kan vara ett namn som ”HUP” eller ett nummer;
                 se ”kill -l” för en lista över signaler

-t, --field-separator=SEP  use SEP instead of non-blank to blank transition
-T, --temporary-directory=DIR  use DIR for temporaries, not $TMPDIR or %s;
                            multiple options specify multiple directories
    --parallel=N          change the number of sorts run concurrently to N
-u, --unique              output only the first of lines with equal keys;
                            with -c, check for strict ordering

-u                         with -lt: sort by, and show, access time;
                           with -l: show access time and sort by name;
                           otherwise: sort by access time, newest first

-u                         med -lt: sortera efter och visa åtkomsttid;
                           med -l: visa åtkomsttid men sortera efter namn;
                           annars: sortera enligt åtkomsttid, nyast först

