Actions:
      -delete -print0 -printf FORMAT -fprintf FILE FORMAT -print 
      -fprint0 FILE -fprint FILE -ls -fls FILE -prune -quit
      -exec COMMAND ; -exec COMMAND {} + -ok COMMAND ;
      -execdir COMMAND ; -execdir COMMAND {} + -okdir COMMAND ;

Åtgärder:
      -delete -print0 -printf FORMAT -fprintf FIL FORMAT -print 
      -fprint0 FIL -fprint FIL -ls -fls FIL -prune -quit
      -exec KOMMANDO ; -exec KOMMANDO {} + -ok KOMMANDO ;
      -execdir KOMMANDO ; -execdir KOMMANDO {} + -okdir KOMMANDO ;

-0, --null                   items are separated by a null, not whitespace;
                               disables quote and backslash processing and
                               logical EOF processing

-i, --replace[=R]            replace R in INITIAL-ARGS with names read
                               from standard input, split at newlines;
                               if R is unspecified, assume {}

-i, --replace[=E]            ersätt E i STARTARGUMENT med namn lästa från
                               standard in; dela vid nyrader;
                               om E utelämnas, anta {}

-r, --no-run-if-empty        if there are no arguments, then do not run COMMAND;
                               if this option is not given, COMMAND will be
                               run at least once
